export const FEATURED_PLAYER_RESEARCH = Object.fromEntries(['Lionel Messi', 'Cristiano Ronaldo', 'Kylian Mbappé', 'Erling Haaland', 'Lamine Yamal', 'Ousmane Dembélé'].map((name) => {
  const stats = researchedStats[name]
  const trophyHistory = researchedTrophyHistories[name]
  return [name, {
    career: { appearances: stats?.career.appearances ?? null, goals: stats?.career.goals ?? null, assists: null },
    international: { team: name === 'Lionel Messi' ? 'Argentina' : name === 'Cristiano Ronaldo' ? 'Portugal' : name === 'Kylian Mbappé' ? 'France' : name === 'Erling Haaland' ? 'Norway' : name === 'Lamine Yamal' ? 'Spain' : 'France', appearances: stats?.international.appearances ?? null, goals: stats?.international.goals ?? null, assists: null },
    trophies: trophyHistory?.trophies || [],
    honors: trophyHistory?.trophies || [],
    trophyStatus: trophyHistory?.status || 'unverified',
    source: stats?.source,
    secondarySources: [trophyHistory?.source, ...(trophyHistory?.secondarySources || [])].filter(Boolean),
    statNote: `${stats?.note || 'Career club and senior national-team totals are transcribed from the linked reference; historical match records can vary by source.'} ${trophyHistory?.status === 'partial' ? 'The trophy cabinet lists known winning editions and is marked partial.' : trophyHistory ? 'The trophy cabinet lists the senior team-title winning editions identified in the linked reference.' : 'A season-by-season trophy history is not yet sourced.'} Assists are left blank where a dependable full-career record is unavailable.`,
  }]
}))

export const ALL_TIME_POSITION_PLAYERS = Object.entries(positions).flatMap(([role, players]) => players.map(([name, country, clubHistory, detail], index) => {
  const researchedTrophies = researchedTrophyHistories[name]
  const careerHighlights = researchedCareerHighlights[name]
  const stats = researchedStats[name]
  const clubs = clubHistory.split(' > ').map((club) => {
    const highlight = careerHighlights?.records.find((record) => record.club === club)
    return { name: club, years: '—', appearances: highlight?.appearances ?? null, goals: highlight?.goals ?? null, assists: null }
  })
  return {
    id: `legend-${slug(role)}-${slug(name)}-${index + 1}`,
    name,
    country,
    role,
    detail,
    clubs,
    careerHighlights: careerHighlights?.records || [],
    career: { appearances: stats?.career.appearances ?? null, goals: stats?.career.goals ?? null, assists: null },
    international: { team: country, appearances: stats?.international.appearances ?? null, goals: stats?.international.goals ?? null, assists: null },
    transferHistory: clubs.map(({ name: club }) => club),
    honors: researchedTrophies?.trophies || [],
    trophies: researchedTrophies?.trophies || [],
    trophyStatus: researchedTrophies?.status || (researchedTrophies ? 'curated' : 'unverified'),
    source: stats?.source || `https://en.wikipedia.org/wiki/${encodeURIComponent(name.replaceAll(' ', '_'))}`,
    secondarySources: [researchedTrophies?.source, careerHighlights?.source, stats?.source].filter(Boolean).filter((url, index, all) => all.indexOf(url) === index),
    statNote: [
      stats ? `${stats.note || 'Career club and senior national-team totals are transcribed from the linked reference; historical match records can vary by source.'}` : 'Career and national-team totals are not yet sourced for this profile.',
      researchedTrophies ? `${researchedTrophies.status === 'partial' ? 'Partial trophy history: ' : ''}the listed title count is based on recorded winning editions, with competition, season and winning club shown above.` : 'A season-by-season trophy history is not yet sourced for this profile.',
      'Assists were not tracked consistently throughout football history and are left blank where no dependable full-career source is available.',
    ].join(' '),
  }
}))
